import{readFileSync}from"fs";import{fileURLToPath}from"url";import path from"path";let generation=0,ignored=new Set;const names=new Map;export const initialize=({port:port,ignore:ignore})=>{ignored=new Set(ignore),port.on("message",()=>{generation++}),port.unref()};export const resolve=async(specifier,context,nextResolve)=>{const result=await nextResolve(specifier,context);return!result.url.startsWith("file:")||result.url.includes("?")||result.url.includes("/node_modules/")||ignored.has((file=>{const visited=[];let dir=path.dirname(file),name="";for(;;){if(names.has(dir)){name=names.get(dir);break}visited.push(dir);try{name=JSON.parse(readFileSync(path.join(dir,"package.json"),"utf8")).name??"";break}catch{const parent=path.dirname(dir);if(parent===dir)break;dir=parent}}return visited.forEach(folder=>names.set(folder,name)),name})(fileURLToPath(result.url)))?result:{...result,url:`${result.url}?dev=${generation}`}};